37	    uint64_t blockDim = 0;
38	    uint64_t aicNum = 0;
39	    uint64_t l1Size = 0;
40	    uint64_t l0aSize = 0;
41	    uint64_t l0bSize = 0;
42	    uint64_t l0cSize = 0;
43	};
44	
