59	class TilingBaseClass {
60	public:
61	    explicit TilingBaseClass(gert::TilingContext* context) : context_(context)
62	    {}
63	
64	    virtual ~TilingBaseClass() = default;
65	
66	    // Tiling执行框架
67	    //     1、GRAPH_SUCCESS: 成功，并且不需要继续执行后续Tiling类的实现
68	    //     2、GRAPH_FAILED: 失败，中止整个Tiling流程
69	    //     3、GRAPH_PARAM_INVALID: 本类不支持，需要继续往下执行其他Tiling类的实现
70	    ge::graphStatus DoTiling()
71	    {
72	        auto ret = GetShapeAttrsInfo();
73	        if (ret != ge::GRAPH_SUCCESS) {
74	            return ret;
75	        }
76	        ret = GetPlatformInfo();
77	        if (ret != ge::GRAPH_SUCCESS) {
78	            return ret;
79	        }
80	        if (!IsCapable()) {
81	            return ge::GRAPH_PARAM_INVALID;
82	        }
83	        ret = DoOpTiling();
84	        if (ret != ge::GRAPH_SUCCESS) {
85	            return ret;
86	        }
87	        ret = DoLibApiTiling();
88	        if (ret != ge::GRAPH_SUCCESS) {
89	            return ret;
90	        }
91	        ret = GetWorkspaceSize();
92	        if (ret != ge::GRAPH_SUCCESS) {
93	            return ret;
94	        }
95	        ret = PostTiling();
96	        if (ret != ge::GRAPH_SUCCESS) {
97	            return ret;
98	        }
99	        context_->SetTilingKey(GetTilingKey());
100	  
101	        return ge::GRAPH_SUCCESS;
102	    }
103	
104	    // 更新 context
105	    virtual void Reset(gert::TilingContext* context)
106	    {
107	        context_ = context;
108	    }
109	
110	protected:
111	    virtual bool IsCapable() = 0;
112	    // 1、获取平台信息比如CoreNum、UB/L1/L0C资源大小
113	    virtual ge::graphStatus GetPlatformInfo() = 0;
114	    // 2、获取INPUT/OUTPUT/ATTR信息
115	    virtual ge::graphStatus GetShapeAttrsInfo() = 0;
116	    // 3、计算数据切分TilingData
117	    virtual ge::graphStatus DoOpTiling() = 0;
118	    // 4、计算高阶API的TilingData
119	    virtual ge::graphStatus DoLibApiTiling() = 0;
120	    // 5、计算TilingKey
121	    [[nodiscard]] virtual uint64_t GetTilingKey() const = 0;
122	    // 6、计算Workspace 大小
123	    virtual ge::graphStatus GetWorkspaceSize() = 0;
124	    // 7、保存Tiling数据
125	    virtual ge::graphStatus PostTiling() = 0;
126	
127	    static uint32_t CalcTschBlockDim(const uint32_t sliceNum, const uint32_t aicCoreNum, const uint32_t aivCoreNum)
128	    {
129	        uint32_t ration;
130	        if (aicCoreNum == 0 || aivCoreNum == 0 || aicCoreNum > aivCoreNum) {
131	            return sliceNum;
132	        }
133	        ration = aivCoreNum / aicCoreNum;
134	        return (sliceNum + (ration - 1)) / ration;
135	    }
