183	int64_t AiInfraKvRmsNormRopeCacheTilingBase::GetComponentStaticQuantMode(
184	    const gert::TilingContext* context, int64_t qScaleIdx, int64_t qOffsetIdx)
185	{
186	    auto scaleShape = context->GetOptionalInputShape(qScaleIdx);
187	    if (scaleShape == nullptr) {
188	        return NON_QUANT_MODE; // NONE Quant
189	    } else {
190	        if (this->methodMode_ == DIM_ONE) {
191	            // V2 Expansion: support Asymmetric Quant
192	            auto offsetShape = context->GetOptionalInputShape(qOffsetIdx);
193	            if (offsetShape) {
194	                return ASYM_QUANT_MODE; // STATIC Asymmetric
195	            }
196	        }
197	        return QUANT_MODE; // STATIC Symmetric
198	    }
199	}
