201	int64_t AiInfraKvRmsNormRopeCacheTilingBase::GetQuantMode(const gert::TilingContext* context)
202	{
203	    this->kStaticQuantMode = GetComponentStaticQuantMode(context, K_ROPE_SCALE_IDX, K_ROPE_OFFSET_IDX);
204	    this->vStaticQuantMode = GetComponentStaticQuantMode(context, C_KV_SCALE_IDX, C_KV_OFFSET_IDX);
205	
206	    // return NON_QUANT_MODE Only when all components use None quant terms
207	    return (kStaticQuantMode > NON_QUANT_MODE || vStaticQuantMode > NON_QUANT_MODE) ? QUANT_MODE : NON_QUANT_MODE;
208	}
