236	ge::graphStatus AiInfraKvRmsNormRopeCacheTilingBase::GetShapeAttrsInfo()
237	{
238	    OP_CHECK_IF(
239	        context_ == nullptr, OP_LOGE(context_->GetNodeName(), "context_ can not be nullptr."), return ge::GRAPH_FAILED);
240	    isRegbase_ = false;
241	    auto compileInfo = context_->GetCompileInfo<AiInfraKvRmsNormRopeCacheCompileInfo>();
242	    OP_CHECK_NULL_WITH_CONTEXT(context_, compileInfo);
243	    auto platformInfo = context_->GetPlatformInfo();
244	    OP_CHECK_NULL_WITH_CONTEXT(context_, platformInfo);
245	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo);
246	    auto socVersion = ascendcPlatform.GetSocVersion();
247	#ifdef USE_ASCEND950
248	    if (socVersion == platform_ascendc::SocVersion::ASCEND950) {
249	        isRegbase_ = true;
250	    }
251	#endif
252	
253	    GetMethodeMode(context_);
254	    // GetQuantMode
255	    quantMode_ = GetQuantMode(context_);
256	    // Basic info
257	    auto kvShapeTuple = GetShapeTuple(context_, KV_INDEX);
258	    auto vCacheShapeTuple = GetShapeTuple(context_, V_CACHE_INDEX);
259	    // Dk
260	    auto cosShapeTuple = GetShapeTuple(context_, COS_INDEX);
261	    // Dv
262	    const gert::StorageShape* gammaShapePtr = context_->GetInputShape(GAMMA_INDEX);
263	    OP_CHECK_NULL_WITH_CONTEXT(context_, gammaShapePtr);
264	    kv_ = std::get<SHAPE_IDX_D>(kvShapeTuple);
265	    dv_ = gammaShapePtr->GetStorageShape().GetDim(0);
266	    dk_ = std::get<SHAPE_IDX_D>(cosShapeTuple);
267	    reciprocal_ = 1.0 / static_cast<float>(dv_);
268	    auto kvDesc = context_->GetInputDesc(KV_INDEX);
269	    OP_CHECK_NULL_WITH_CONTEXT(context_, kvDesc);
270	    kvDtype_ = kvDesc->GetDataType();
271	    if (kvDtype_ == ge::DT_FLOAT) {
272	        kvDtypeSize_ = FLOAT32_BYTES;
273	    }
274	
275	    if (kvDtype_ == ge::DT_FLOAT16 || kvDtype_ == ge::DT_BF16) {
276	        kvDtypeSize_ = FLOAT16_BYTES;
277	    }
278	
279	    int64_t batchSize = std::get<SHAPE_IDX_B>(kvShapeTuple);
280	    int64_t numHead = std::get<SHAPE_IDX_N>(kvShapeTuple);
281	    int64_t seqLen = std::get<SHAPE_IDX_S>(kvShapeTuple);
282	    cacheLength_ = std::get<SHAPE_IDX_S>(vCacheShapeTuple);
283	    blockSize_ = std::get<SHAPE_IDX_BLOCK_SIZE>(vCacheShapeTuple);
284	    isMTP_ = (seqLen > 1);
285	    OP_CHECK_IF(batchSize < 1, OP_LOGE(context_->GetNodeName(), "batchSize should >= 1."), return ge::GRAPH_FAILED);
286	    OP_CHECK_IF(seqLen < 1, OP_LOGE(context_->GetNodeName(), "seqLen should >= 1."), return ge::GRAPH_FAILED);
287	
288	    if (methodMode_ == 0) {
289	        OP_CHECK_IF(numHead != 1, OP_LOGE(context_->GetNodeName(), "numHead should == 1."), return ge::GRAPH_FAILED);
290	    } else {
291	        OP_CHECK_IF(
292	            (numHead != 1 && numHead != 2 && numHead != 4 && numHead != 8),
293	            OP_LOGE(context_->GetNodeName(), "numHead should == 1 or 2 or 4 or 8."), return ge::GRAPH_FAILED);
294	    }
295	
296	    if (methodMode_ == 1) {
297	        auto vShape = GetOptionalShapeTuple(context_, V_IDX);
298	        vlen_ = std::get<SHAPE_IDX_D>(vShape);
299	        OP_CHECK_IF(
300	            !CheckVValid(context_, batchSize, numHead, seqLen, vlen_),
301	            OP_LOGE(context_->GetNodeName(), "v shape is invalid."), return ge::GRAPH_FAILED);
302	    }
303	    OP_CHECK_IF(
304	        !CheckKvValid(context_, batchSize, numHead, seqLen, kv_),
305	        OP_LOGE(context_->GetNodeName(), "kv shape is invalid."), return ge::GRAPH_FAILED);
306	    OP_CHECK_IF(
307	        !CheckCosSinValid(context_, batchSize, numHead, seqLen, dk_),
308	        OP_LOGE(context_->GetNodeName(), "cos or sin shape is invalid."), return ge::GRAPH_FAILED);
309	    OP_CHECK_IF(
310	        !CheckGammaValid(context_, dv_), OP_LOGE(context_->GetNodeName(), "gamma shape is invalid."),
311	        return ge::GRAPH_FAILED);
312	    // Attrs info
313	    auto attrs = context_->GetAttrs();
314	    OP_CHECK_NULL_WITH_CONTEXT(context_, attrs);
315	    const float* epsilon = attrs->GetFloat(0);
316	    OP_CHECK_NULL_WITH_CONTEXT(context_, epsilon);
317	
318	    epsilon_ = *epsilon;
319	    const char* tmpmode = attrs->GetStr(CACHE_MODE_IDX);
320	    if (tmpmode != nullptr) {
321	        std::string cacheMode = tmpmode;
322	        isPagedAttention_ = (cacheMode == "PA" || cacheMode == "PA_BNSD");
323	        std::unordered_map<std::string, CacheMode> cacheModeMap = {
324	            {"PA", CacheMode::PA},
325	            {"PA_BNSD", CacheMode::PA},
326	            {"PA_NZ", CacheMode::PA_NZ},
327	            {"PA_BLK_BNSD", CacheMode::PA_BLK_BNSD},
328	            {"PA_BLK_NZ", CacheMode::PA_BLK_NZ}};
329	        auto it = cacheModeMap.find(cacheMode);
330	        currentCacheMode_ = (it != cacheModeMap.end()) ? it->second : CacheMode::NORM;
331	    } else {
332	        isPagedAttention_ = false;
333	        currentCacheMode_ = CacheMode::NORM;
334	    }
335	    const bool* isOutputKv = attrs->GetBool(IS_OUTPUT_KV_IDX);
336	    OP_CHECK_NULL_WITH_CONTEXT(context_, isOutputKv);
337	    isOutputKv_ = *isOutputKv;
338	    OP_CHECK_IF(
339	        !CheckIndexValid(context_, batchSize, seqLen, blockSize_, currentCacheMode_),
340	        OP_LOGE(context_->GetNodeName(), "index shape is invalid."), return ge::GRAPH_FAILED);
341	    return ge::GRAPH_SUCCESS;
342	}
