27	// 输入tensor索引
28	static constexpr uint32_t INPUT_VAR_INDEX = 0;
29	static constexpr uint32_t INPUT_INDICES_INDEX = 1;
30	static constexpr uint32_t INPUT_UPDATE_INDEX = 2;
31	
32	// 维度常量
33	static constexpr int64_t INPUT_DIM_NUM = 3;     // input shape: (b_n, b_s, D)
34	static constexpr int64_t INDICES_DIM_NUM = 2;   // indices shape: (T, 2)
35	static constexpr int64_t UPDATE_DIM_NUM = 2;    // update shape: (T, D)
36	static constexpr int64_t INDICES_LAST_DIM = 2;  // indices最后一维固定为2
37	
38	// input维度索引
39	static constexpr int64_t INPUT_DIM_BN_INDEX = 0;  // input第0维索引 (b_n)
40	static constexpr int64_t INPUT_DIM_BS_INDEX = 1;  // input第1维索引 (b_s)
41	static constexpr int64_t INPUT_DIM_D_INDEX = 2;   // input第2维索引 (D)
42	
43	// 内存对齐与UB布局
44	static constexpr int64_t ALIGN_BYTES = 32;
45	static constexpr int64_t RESERVED_UB_SIZE = 4 * 1024;  // 4KB预留给栈和临时变量
46	static constexpr int64_t DOUBLE_BUFFER_NUM = 2;
47	static constexpr int64_t DATA_COPY_MAX_BLOCK = 4064;
48	
49	// shape取值范围约束 (闭区间)
50	static constexpr int64_t BN_MIN = 1;
51	static constexpr int64_t BN_MAX = 2 * 1024 * 1024;       // 2M
52	static constexpr int64_t BS_MIN = 1;
53	static constexpr int64_t BS_MAX = 1024;
54	static constexpr int64_t D_MIN = 1;
55	static constexpr int64_t D_MAX = 2048;
56	static constexpr int64_t T_MIN = 1;
57	static constexpr int64_t T_MAX = 1024 * 1024;       // 1M
58	
59	static constexpr uint64_t FULL_LOAD_TILING_KEY = 1000;
60	
61	
62	static inline int64_t AlignUp(int64_t size, int64_t alignment)
63	{
64	    if (alignment <= 0) {
65	        return size;
66	    }
67	    return (size + alignment - 1) / alignment * alignment;
68	}
69	
70	static inline int64_t CeilDiv(int64_t a, int64_t b)
71	{
72	    if (b <= 0) {
73	        return a;
74	    }
75	    return (a + b - 1) / b;
76	}
