149	ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::GetIndicesShape()
150	{
151	    // ========== 获取indices信息: shape (T, 2), 连续, INT32/INT64 ==========
152	    auto indicesDesc = context_->GetInputDesc(INPUT_INDICES_INDEX);
153	    OP_CHECK_NULL_WITH_CONTEXT(context_, indicesDesc);
154	    indicesDtype_ = indicesDesc->GetDataType();
155	
156	    OP_CHECK_IF(indicesDtype_ != ge::DT_INT32 && indicesDtype_ != ge::DT_INT64,
157	        OP_LOGE(context_->GetNodeName(), "indices dtype only supports INT32/INT64"),
158	        return ge::GRAPH_FAILED);
159	
160	    auto indicesShapePtr = context_->GetInputShape(INPUT_INDICES_INDEX);
161	    OP_CHECK_NULL_WITH_CONTEXT(context_, indicesShapePtr);
162	    auto indicesShape = indicesShapePtr->GetStorageShape();
163	
164	    OP_CHECK_IF(indicesShape.GetDimNum() != static_cast<size_t>(INDICES_DIM_NUM),
165	        OP_LOGE(context_->GetNodeName(),
166	                "indices should be 2D (T, 2), but got %zu dims", indicesShape.GetDimNum()),
167	        return ge::GRAPH_FAILED);
168	
169	    T_ = indicesShape.GetDim(0);
170	    int64_t indicesDim1 = indicesShape.GetDim(1);
171	    OP_CHECK_IF(indicesDim1 != INDICES_LAST_DIM,
172	        OP_LOGE(context_->GetNodeName(), "indices last dim should be 2, but got %ld", indicesDim1),
173	        return ge::GRAPH_FAILED);
174	    return ge::GRAPH_SUCCESS;
175	}
