355	void AiInfraScatterBlockUpdateBaseTiling::PrintTilingData()
356	{
357	    OP_LOGD(context_->GetNodeName(),
358	        "TilingData: totalIndicesCount=%ld, updateDimSize=%ld, usedCoreNum=%d, "
359	        "eachCoreIndexCount=%ld, tailCoreIndexCount=%ld, oneIndexAlign=%ld, "
360	        "oneUpdateAlign=%ld, indicesPerLoad=%ld, maxIndicesPerLoad=%ld, "
361	        "inputStride0=%ld, inputStride1=%ld, indicesTypeSize=%ld, updateTypeSize=%ld",
362	        tilingData_.get_totalIndicesCount(), tilingData_.get_updateDimSize(),
363	        tilingData_.get_usedCoreNum(), tilingData_.get_eachCoreIndexCount(),
364	        tilingData_.get_tailCoreIndexCount(), tilingData_.get_oneIndexSize(),
365	        tilingData_.get_oneUpdateAlignSize(), tilingData_.get_indicesPerLoad(),
366	        tilingData_.get_maxIndicesPerLoad(), tilingData_.get_inputStride0(),
367	        tilingData_.get_inputStride1(), tilingData_.get_indicesTypeSize(),
368	        tilingData_.get_updateTypeSize());
369	}
