363	    {
364	        const char* opType = context->GetNodeType();
365	        auto tilingTemplateRegistryMap = GetTilingTemplates(opType);
366	        for (auto it = tilingTemplateRegistryMap.begin(); it != tilingTemplateRegistryMap.end(); ++it) {
367	            auto tilingTemplate = it->second(context);
368	            if (tilingTemplate != nullptr) {
369	                ge::graphStatus status = tilingTemplate->DoTiling();
370	                if (status != ge::GRAPH_PARAM_INVALID) {
371	                    OP_LOGD(context, "Do general op tiling success priority=%d", it->first);
372	                    return status;
373	                }
374	                OP_LOGD(context, "Ignore general op tiling priority=%d", it->first);
375	            }
376	        }
