381	    ge::graphStatus DoTilingImpl(gert::TilingContext* context, const std::vector<int32_t>& priorities)
382	    {
383	        const char* opType = context->GetNodeType();
384	        auto tilingTemplateRegistryMap = GetTilingTemplates(opType);
385	        for (auto priorityId : priorities) {
386	            auto templateFunc = tilingTemplateRegistryMap[priorityId](context);
387	            if (templateFunc != nullptr) {
388	                ge::graphStatus status = templateFunc->DoTiling();
389	                if (status == ge::GRAPH_SUCCESS) {
